# generate_tool_skills.py - on-demand toolbelt skill generator + inventory probe.
#
# Probes installed tool surfaces (PATH, pip console scripts, npm, uv, cargo),
# diffs them against azazael/skills coverage, writes logs/tool_inventory.json,
# and can emit a skill stub for ONE tool at a time. Mass generation is banned
# by precedent (flet_test/record_lessons.py: 1228 auto-generated skills = 188k
# tokens, pruned to 140) - generate on demand, never in bulk.
#
# Usage:
#   python src/SCRIPTS/generate_tool_skills.py              # census -> logs/tool_inventory.json
#   python src/SCRIPTS/generate_tool_skills.py --tool NAME  # emit skills/azazael-tool-NAME.md stub
import json
import os
import shutil
import subprocess
import sys
from datetime import datetime, timezone
from importlib import metadata
from pathlib import Path
from typing import List

#: Swallows recorded when the failure ledger is unavailable (it is a stdlib-only
#: leaf, so this fallback should never fire -- if it does, the ledger is missing).

try:
    from CORE.failure_ledger import note_failure
except ImportError:                               # never break the host
    def note_failure(where: str, exc: BaseException | None = None) -> None:
        pass  # ledger missing; evidence-vs-silence tradeoff capped here

ROOT = Path(__file__).resolve().parents[2]
SKILLS = ROOT / "skills"
OUT = ROOT / "logs" / "tool_inventory.json"
PREFIXES = ("azazael_pkg314t_", "azazael_pkg_", "azazael_bin_", "azazael_tool_")


def norm(s):
    return "".join(ch if ch.isalnum() else "_" for ch in str(s).strip().lower()).strip("_")


def covered_tokens():
    toks = set()
    for f in SKILLS.glob("*.md"):
        n = norm(f.stem)
        toks.add(n)
        for pre in PREFIXES:
            if n.startswith(pre):
                rest = n[len(pre):]
                if rest:
                    toks.add(rest)
                break
    return toks


def scan_path():
    skip = ("windows", "system32", "syswow64", "wbem", "windowsapps", "powershell")
    out = {}
    for d in os.environ.get("PATH", "").split(os.pathsep):
        p = Path(d)
        if not p.is_dir() or any(s in str(p).lower() for s in skip):
            continue
        try:
            for f in p.iterdir():
                if f.suffix.lower() in (".exe", ".cmd", ".bat") and f.is_file():
                    out.setdefault(f.stem.lower(), str(p))
        except OSError as exc:
            note_failure("generate_tool_skills:L56", exc)
    return out


def scan_pip():
    rows = {}
    for dist in metadata.distributions():
        try:
            name = (dist.metadata.get("Name") or "?").lower()
            bins = sorted({ep.name for ep in dist.entry_points
                           if getattr(ep, "group", "") == "console_scripts"})
        except Exception as exc:
            note_failure("generate_tool_skills:L68", exc)
            continue
        if bins:
            rows[name] = bins
    return rows


def scan_pm(cmd):
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=60, encoding="utf-8", errors="replace")
        return [ln.strip() for ln in (r.stdout or "").splitlines() if ln.strip()]
    except Exception as exc:
        note_failure("generate_tool_skills:L79", exc)
        return []


def emit_stub(name_raw):
    name = norm(name_raw)
    stub = SKILLS / ("azazael-tool-" + name + ".md")
    body = [
        "---",
        "name: azazael-tool-" + name,
        "description: On-demand tool skill stub for " + name + " (generated by generate_tool_skills.py; document only verified commands).",
        "metadata:",
        "  category: tools",
        "  project: azazael",
        "  priority: medium",
        "  auto_load: false",
        "---",
        "",
        "# " + name,
        "",
        "Probe at generation time:",
        "- which: " + str(shutil.which(name_raw) or "not on PATH"),
        "",
        "## Usage",
        "TODO: replace with verified usage (run the tool first, cite output).",
        "",
    ]
    stub.write_text(chr(10).join(body), encoding="utf-8")
    print("wrote", stub)
    return 0


def main(argv):
    if len(argv) >= 3 and argv[1] == "--tool":
        return emit_stub(argv[2])
    toks = covered_tokens()
    inv = {
        "generated": datetime.now(timezone.utc).isoformat(),
        "skills": len(list(SKILLS.glob("*.md"))),
        "path_tools": scan_path(),
        "pip_console_scripts": scan_pip(),
        "npm_global": scan_pm(["npm", "ls", "-g", "--depth=0"]),
        "uv_tools": scan_pm(["uv", "tool", "list"]),
        "cargo": scan_pm(["cargo", "install", "--list"]),
        "covered_tokens": sorted(toks),
    }
    OUT.write_text(json.dumps(inv, indent=1), encoding="utf-8")
    uncovered = [n for n in inv["path_tools"] if norm(n) not in toks]
    print("inventory written", OUT)
    print("path tools", len(inv["path_tools"]), "uncovered", len(uncovered))
    print("pip pkgs with console bins", len(inv["pip_console_scripts"]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))